interface Usuario {
  id: number;
  nombre: string;
  email: string;
}

export function actualizarUsuario(usuario: Usuario, cambios: Partial<Usuario>): Usuario {
  // Un objeto nuevo: el usuario original no se muta.
  return { ...usuario, ...cambios };
}

