kata.solucion:
export function contarPalabras(texto: string): Record<string, number> {
  const cuenta: Record<string, number> = {};
  for (const palabra of texto.split(/\s+/).filter(Boolean)) {
    cuenta[palabra] = (cuenta[palabra] ?? 0) + 1;
  }
  return cuenta;
}
